// MOUNTAIN PALETTE — the campus recolour rule for public/brand/mt-cook.svg.
//
// The mountain is two hue families — lit faces (the artwork's reds → the campus PRIMARY) and
// shaded faces (its blues → the campus SECONDARY) — and its texture is the per-path lightness
// variation inside each family. scripts/mountain-asset.ts bucketed that variation into ≤ 10 steps
// per family and recorded each step's lightness OFFSET from the family's median shade (the table
// between the @generated markers below). mountainPalette() re-applies those offsets to ANY
// school's pair: the median step is the school colour untouched, the other steps are the same
// colour moved by the same amount the artwork moved — so every campus gets the same mountain.
//
// The one guard is the bolt's light-colour rule (bolt-palette.whyTooLight): a white / cream /
// silver secondary (Tennessee, Alabama, Nebraska…) would have its lit steps blow out into the page
// cream. Rather than a second rule, the same test picks a LOWER ceiling, and the whole family is
// compressed to fit under it with ordering intact — so the face reads as pale stone, still
// textured, never a white hole.
import { LIGHT_LIGHTNESS, NEAR_WHITE_LIGHTNESS } from "./bolt/bolt-config";
import { hexToRgb, rgbToHex, whyTooLight } from "./bolt/bolt-palette";

/** One lightness step of one family: `offset` is HSL-L relative to the family median, `share` is
 *  the fraction of that family's fills the step paints (a highlight speck is not the mountain). */
export type MountainStep = { family: "p" | "s"; step: number; offset: number; share: number };

/** `--mtn-p-3`, `--mtn-s-0` … the custom-property names the SVG fills read. */
export const STEP_VAR_PREFIX = "--mtn-";

/** The mountain as shipped — Mt Cook's own red and blue medians, so the default palette is the
 *  artwork itself. Matches styles.css `--bolt-primary` / `--bolt-secondary` on the generic home. */
export const DEFAULT_MOUNTAIN_PRIMARY = "#C62828";
export const DEFAULT_MOUNTAIN_SECONDARY = "#1565C0";

/** A step painting at least this share of its family is CORE — the fit keeps the core inside the
 *  bounds outright; the specks outside it (a five-path pink glint, two lilac ridges) are soft-
 *  clamped instead, so they can never drag the whole face away from the school colour. */
export const CORE_MIN_SHARE = 0.02;
/** Width of the soft-clamp zone below the ceiling / above the floor. */
export const SOFT_ZONE = 0.08;
/** Darkest any step may go (HSL L). A shadow face at 0 lightness is a hole, not a shadow. */
export const MOUNTAIN_FLOOR_LIGHTNESS = 0.05;
/** Ceiling for a colour that PASSES the bolt's light test — just under near-white. */
export const MOUNTAIN_CEILING_LIGHTNESS = NEAR_WHITE_LIGHTNESS - 0.04;
/** Ceiling for a colour that FAILS it (white / cream / silver): the bolt's "merely light" line,
 *  so the brightest face of a white-secondary school is a readable pale stone, not page cream. */
export const MOUNTAIN_LIGHT_CEILING_LIGHTNESS = LIGHT_LIGHTNESS + 0.14;

